using System;using System.IO;using System.Linq;using System.Reflection;using UnityEngine;using UnityEditor;using Newtonsoft.Json.Linq;
public static class AuditPenguinFaceShaderV3
{
 static string Dir=>Path.GetFullPath(Application.dataPath+"/../../../art/reskin/penguin-expedition/face-fix-v3");
 static Shader Compile(string source,string name){source=source.Replace("Shader \"Game/PenguinExpression\"","Shader \"Hidden/"+name+"\"");var methods=typeof(ShaderUtil).GetMethods(BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Static).Where(m=>m.Name=="CreateShaderAsset").ToArray();var method=methods.FirstOrDefault(m=>m.GetParameters().Select(p=>p.ParameterType).SequenceEqual(new[]{typeof(string),typeof(bool)}))??methods.First(m=>m.GetParameters().Select(p=>p.ParameterType).SequenceEqual(new[]{typeof(string)}));var args=method.GetParameters().Length==2?new object[]{source,false}:new object[]{source};var shader=(Shader)method.Invoke(null,args);if(ShaderUtil.ShaderHasError(shader))throw new Exception("Shader compilation failed: "+name);return shader;}
 static Vector4 V(JToken a)=>new Vector4((float)a[0],(float)a[1],(float)a[2],(float)a[3]);
 static Texture2D Render(Material mat,Texture2D texture)
 {var old=RenderTexture.active;var rt=RenderTexture.GetTemporary(texture.width,texture.height,0,RenderTextureFormat.ARGB32,RenderTextureReadWrite.Linear);var output=new Texture2D(texture.width,texture.height,TextureFormat.RGBA32,false,true);try{RenderTexture.active=rt;GL.Clear(false,true,Color.clear);UnityEngine.Graphics.Blit(texture,rt,mat);output.ReadPixels(new Rect(0,0,rt.width,rt.height),0,0);output.Apply();return output;}finally{RenderTexture.active=old;RenderTexture.ReleaseTemporary(rt);}}
 public static string Run()
 {
  if(Application.dataPath!="/Volumes/ZHITAI_1T/IdleCatGunner/reconstruction/CatGunnerUnityClient/Assets")throw new Exception("Wrong project");Directory.CreateDirectory(Dir+"/gpu");var before=Compile(File.ReadAllText(Dir+"/backup/PenguinExpression.shader"),"PenguinFaceBefore");var after=Compile(File.ReadAllText(Dir+"/prepared/PenguinExpression.shader"),"PenguinFaceAfter");var rows=JArray.Parse(File.ReadAllText(Path.GetFullPath(Application.dataPath+"/../../../art/reskin/penguin-expedition/grip-expression-v2/assets.json")));var records=new System.Collections.Generic.List<object>();
  try{foreach(var row in rows){int id=(int)row["index"];var tex=AssetDatabase.LoadAssetAtPath<Texture2D>((string)row["file"]);var ma=new Material(before);var mb=new Material(after);foreach(var m in new[]{ma,mb}){m.SetTexture("_MainTex",tex);m.SetVector("_EyeA",V(row["eyes"][0]));m.SetVector("_EyeB",V(row["eyes"][1]));m.SetVector("_Mouth",V(row["mouth"]));}var neutral=Render(mb,tex);var baseline=neutral.GetPixels();int samples=0;float oldError=0,newError=0;
   foreach(var state in new[]{"blink","happy"}){foreach(var m in new[]{ma,mb}){m.SetFloat("_Blink",state=="blink"?1:0);m.SetFloat("_Happy",state=="happy"?1:0);}var a=Render(ma,tex);var b=Render(mb,tex);var pa=a.GetPixels();var pb=b.GetPixels();foreach(var e in new[]{V(row["eyes"][0]),V(row["eyes"][1])})foreach(float sx in new[]{-.98f,.98f})foreach(float sy in new[]{-.96f,.96f}){int x=Mathf.Clamp(Mathf.RoundToInt((e.x+sx*e.z)*tex.width),0,tex.width-1),y=Mathf.Clamp(Mathf.RoundToInt((e.y+sy*e.w)*tex.height),0,tex.height-1),i=y*tex.width+x;if(baseline[i].a<.99f||Mathf.Min(baseline[i].r,baseline[i].g,baseline[i].b)<.78f)continue;samples++;oldError+=Mathf.Abs(pa[i].r-baseline[i].r)+Mathf.Abs(pa[i].g-baseline[i].g)+Mathf.Abs(pa[i].b-baseline[i].b);newError+=Mathf.Abs(pb[i].r-baseline[i].r)+Mathf.Abs(pb[i].g-baseline[i].g)+Mathf.Abs(pb[i].b-baseline[i].b);}
    File.WriteAllBytes(Dir+"/gpu/"+id.ToString("00")+"-"+state+"-before.png",a.EncodeToPNG());File.WriteAllBytes(Dir+"/gpu/"+id.ToString("00")+"-"+state+"-after.png",b.EncodeToPNG());UnityEngine.Object.DestroyImmediate(a);UnityEngine.Object.DestroyImmediate(b);}
   File.WriteAllBytes(Dir+"/gpu/"+id.ToString("00")+"-neutral.png",neutral.EncodeToPNG());records.Add(new{id,samples,oldCornerError=oldError/Mathf.Max(1,samples),newCornerError=newError/Mathf.Max(1,samples)});UnityEngine.Object.DestroyImmediate(neutral);UnityEngine.Object.DestroyImmediate(ma);UnityEngine.Object.DestroyImmediate(mb);}
   File.WriteAllText(Dir+"/gpu-audit.json",Newtonsoft.Json.JsonConvert.SerializeObject(new{source="Actual GPU shader rendering of current 25 body textures; no scene, actor, profile or material changes",records},Newtonsoft.Json.Formatting.Indented));return "Rendered blink/smile comparison for 25 skins using temporary shaders; current scene untouched.";
  }finally{UnityEngine.Object.DestroyImmediate(before);UnityEngine.Object.DestroyImmediate(after);}
 }
}
